                onMouseEnter: (e) => {
                  if (!showMenu) {
                    e.currentTarget.style.color = 'var(--dsw-alias-label-primary)';
                    e.currentTarget.style.background = 'var(--dsw-alias-fill-l1)';
                  }
                },
                onMouseLeave: (e) => {
                  if (!showMenu) {
                    e.currentTarget.style.color = 'var(--dsw-alias-label-secondary)';
                    e.currentTarget.style.background = 'transparent';
                  }
                }
              }, 
                React.createElement('span', { style: { fontSize: '18px' } }, '👥'),
                wide && React.createElement('span', {}, t('button.label'))
              ),

              showMenu && React.createElement('div', {
                onClick: (e) => e.stopPropagation(),
                style: {
                  position: 'fixed',
                  left: menuPosition.x + 'px',
                  top: menuPosition.y + 'px',
                  width: '240px',
                  background: 'var(--dsw-alias-fill-elevated)',
                  border: '1px solid var(--dsw-alias-border-l2)',
                  borderRadius: '12px',
                  boxShadow: '0 8px 24px rgba(0,0,0,0.15)',
                  padding: '8px',
                  zIndex: 9999
                }
              },
                React.createElement('div', {
                  style: {
                    padding: '8px 12px',
                    fontSize: '12px',
                    fontWeight: 600,
                    color: 'var(--dsw-alias-label-tertiary)',
                    borderBottom: '1px solid var(--dsw-alias-border-l1)',
                    marginBottom: '4px'
                  }
                }, t('menu.title')),

                ...experts.map(expert =>
                  React.createElement('button', {
                    key: expert.id,
                    onClick: () => handleExpertClick(expert),
                    style: {
                      width: '100%',
                      padding: '10px 12px',
                      fontSize: '13px',
                      color: 'var(--dsw-alias-label-primary)',
                      background: 'transparent',
                      border: 'none',
                      borderRadius: '6px',
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '10px',
                      textAlign: 'left',
                      transition: 'background 0.1s ease'
                    },
                    onMouseEnter: (e) => {
                      e.currentTarget.style.background = 'var(--dsw-alias-fill-l1)';
                    },
                    onMouseLeave: (e) => {
                      e.currentTarget.style.background = 'transparent';
                    }
                  },
                    React.createElement('span', { style: { fontSize: '20px' } }, expert.icon),
                    React.createElement('span', null, expert.name)
                  )
                )
              )
            );
          }
        )
      );
    }

    exports.apply = apply;
    exports.inject = inject;
    return module.exports;
  }
});
